Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'CARPRATOTURNONOME' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoTurnoNome1.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurnoNome1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarPratoTurnoNomeDescription = format('%1 (%2)', "Turno Nome", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FiltercarPratoTurnoNomeDescription = format('%1 (%2)', "Turno Nome", "WWP_FilterContains") EndCase &carPratoTurnoNome = &carPratoTurnoNome1 print printBlockFiltercarPratoTurnoNome EndIf Case &DynamicFiltersSelector1 = !'CARPRATODATA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoData1.FromString(&GridStateDynamicFilter.Value) &carPratoData_To1.FromString(&GridStateDynamicFilter.ValueTo) If not &carPratoData1.IsEmpty() OR not &carPratoData_To1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarPratoDataDescription = format('%1 (%2)', "Data", "WWP_FilterRange") &carPratoData = &carPratoData1 print printBlockFiltercarPratoData &FiltercarPratoDataDescription = format('%1 (%2) %3', "Data", "WWP_FilterRange", "") &carPratoData = &carPratoData_To1 print printBlockFiltercarPratoData EndCase EndIf Case &DynamicFiltersSelector1 = !'CARPRATOREFEICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoRefeicao1.FromString(&GridStateDynamicFilter.Value) If not &carPratoRefeicao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarPratoRefeicaoDescription = format('%1 (%2)', "do Prato)", "=") EndCase &carPratoRefeicao = &carPratoRefeicao1 print printBlockFiltercarPratoRefeicao EndIf Case &DynamicFiltersSelector1 = !'CARPRATOTURNO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &carPratoTurno1.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurno1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FiltercarPratoTurnoDescription = format('%1 (%2)', "Tipo de Refeição", "=") EndCase &carPratoTurno = &carPratoTurno1 print printBlockFiltercarPratoTurno EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'CARPRATOTURNONOME' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoTurnoNome2.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurnoNome2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarPratoTurnoNomeDescription = format('%1 (%2)', "Turno Nome", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FiltercarPratoTurnoNomeDescription = format('%1 (%2)', "Turno Nome", "WWP_FilterContains") EndCase &carPratoTurnoNome = &carPratoTurnoNome2 print printBlockFiltercarPratoTurnoNome EndIf Case &DynamicFiltersSelector2 = !'CARPRATODATA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoData2.FromString(&GridStateDynamicFilter.Value) &carPratoData_To2.FromString(&GridStateDynamicFilter.ValueTo) If not &carPratoData2.IsEmpty() OR not &carPratoData_To2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarPratoDataDescription = format('%1 (%2)', "Data", "WWP_FilterRange") &carPratoData = &carPratoData2 print printBlockFiltercarPratoData &FiltercarPratoDataDescription = format('%1 (%2) %3', "Data", "WWP_FilterRange", "") &carPratoData = &carPratoData_To2 print printBlockFiltercarPratoData EndCase EndIf Case &DynamicFiltersSelector2 = !'CARPRATOREFEICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoRefeicao2.FromString(&GridStateDynamicFilter.Value) If not &carPratoRefeicao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarPratoRefeicaoDescription = format('%1 (%2)', "do Prato)", "=") EndCase &carPratoRefeicao = &carPratoRefeicao2 print printBlockFiltercarPratoRefeicao EndIf Case &DynamicFiltersSelector2 = !'CARPRATOTURNO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &carPratoTurno2.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurno2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FiltercarPratoTurnoDescription = format('%1 (%2)', "Tipo de Refeição", "=") EndCase &carPratoTurno = &carPratoTurno2 print printBlockFiltercarPratoTurno EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'CARPRATOTURNONOME' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoTurnoNome3.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurnoNome3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarPratoTurnoNomeDescription = format('%1 (%2)', "Turno Nome", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FiltercarPratoTurnoNomeDescription = format('%1 (%2)', "Turno Nome", "WWP_FilterContains") EndCase &carPratoTurnoNome = &carPratoTurnoNome3 print printBlockFiltercarPratoTurnoNome EndIf Case &DynamicFiltersSelector3 = !'CARPRATODATA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoData3.FromString(&GridStateDynamicFilter.Value) &carPratoData_To3.FromString(&GridStateDynamicFilter.ValueTo) If not &carPratoData3.IsEmpty() OR not &carPratoData_To3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarPratoDataDescription = format('%1 (%2)', "Data", "WWP_FilterRange") &carPratoData = &carPratoData3 print printBlockFiltercarPratoData &FiltercarPratoDataDescription = format('%1 (%2) %3', "Data", "WWP_FilterRange", "") &carPratoData = &carPratoData_To3 print printBlockFiltercarPratoData EndCase EndIf Case &DynamicFiltersSelector3 = !'CARPRATOREFEICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoRefeicao3.FromString(&GridStateDynamicFilter.Value) If not &carPratoRefeicao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarPratoRefeicaoDescription = format('%1 (%2)', "do Prato)", "=") EndCase &carPratoRefeicao = &carPratoRefeicao3 print printBlockFiltercarPratoRefeicao EndIf Case &DynamicFiltersSelector3 = !'CARPRATOTURNO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &carPratoTurno3.FromString(&GridStateDynamicFilter.Value) If not &carPratoTurno3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FiltercarPratoTurnoDescription = format('%1 (%2)', "Tipo de Refeição", "=") EndCase &carPratoTurno = &carPratoTurno3 print printBlockFiltercarPratoTurno EndIf EndCase EndIf EndIf EndIf If not (&TFcarPratoData.IsEmpty() AND &TFcarPratoData_To.IsEmpty()) print printBlockTFcarPratoData &TFcarPratoData_To_Description = format('%1 (%2)', "Data", "WWP_TSTo") print printBlockTFcarPratoData_To EndIf If not (&TFcarPratoTurnoHorario.IsEmpty() AND &TFcarPratoTurnoHorario_To.IsEmpty()) print printBlockTFcarPratoTurnoHorario &TFcarPratoTurnoHorario_To_Description = format('%1 (%2)', "Horário", "WWP_TSTo") print printBlockTFcarPratoTurnoHorario_To EndIf If not &TFcarPratoTurno_Sel.IsEmpty() print printBlockTFcarPratoTurno_Sel Else If not &TFcarPratoTurno.IsEmpty() print printBlockTFcarPratoTurno EndIf EndIf If not &TFcarPratoRefeicao_Sel.IsEmpty() print printBlockTFcarPratoRefeicao_Sel Else If not &TFcarPratoRefeicao.IsEmpty() print printBlockTFcarPratoRefeicao EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
