Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnscardapioprato order carPratoData carPratoHorario when &OrderedBy = 1 order prefCodigo carDapCodigo carPratoData when &OrderedBy = 2 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) when &OrderedBy = 2 AND &OrderedDsc = True order prefCodigo carDapCodigo carPratoData carPratoTurnoHorario when &OrderedBy = 3 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) (carPratoTurnoHorario) when &OrderedBy = 3 AND &OrderedDsc = True order prefCodigo carDapCodigo carPratoData carPratoTurno when &OrderedBy = 4 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) (carPratoTurno) when &OrderedBy = 4 AND &OrderedDsc = True order prefCodigo carDapCodigo carPratoData carPratoRefeicao when &OrderedBy = 5 AND &OrderedDsc = False order (prefCodigo) (carDapCodigo) (carPratoData) (carPratoRefeicao) when &OrderedBy = 5 AND &OrderedDsc = True
using trnscardapiopratoWWDS(&prefCodigo, &carDapCodigo, &DynamicFiltersSelector1, &DynamicFiltersOperator1, &carPratoTurnoNome1, &carPratoData1 , &carPratoData_To1, &carPratoRefeicao1, &carPratoTurno1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2 , &carPratoTurnoNome2, &carPratoData2, &carPratoData_To2, &carPratoRefeicao2, &carPratoTurno2, &DynamicFiltersEnabled3 , &DynamicFiltersSelector3, &DynamicFiltersOperator3, &carPratoTurnoNome3, &carPratoData3, &carPratoData_To3, &carPratoRefeicao3 , &carPratoTurno3, &TFcarPratoData, &TFcarPratoData_To, &TFcarPratoTurnoHorario, &TFcarPratoTurnoHorario_To, &TFcarPratoTurno , &TFcarPratoTurno_Sel, &TFcarPratoRefeicao, &TFcarPratoRefeicao_Sel) Where prefCodigo = &prefCodigo
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnscardapiopratoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnscardapiopratoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnscardapiopratoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFCARPRATODATA" &TFcarPratoData.FromString(&GridStateFilterValue.Value) &TFcarPratoData_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARPRATOTURNOHORARIO" &TFcarPratoTurnoHorario.FromString(&GridStateFilterValue.Value) &TFcarPratoTurnoHorario_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFCARPRATOTURNO" &TFcarPratoTurno.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARPRATOTURNO_SEL" &TFcarPratoTurno_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARPRATOREFEICAO" &TFcarPratoRefeicao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFCARPRATOREFEICAO_SEL" &TFcarPratoRefeicao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&PREFCODIGO" &prefCodigo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"PARM_&CARDAPCODIGO" &carDapCodigo.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
